head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderColor]<br/>Cell 정보를 사용하여 특정 Header Cell 의 글자색을 설정합니다.",
    "validation" : [
        "cellInfo(필수) 파라미터로 글자색을 설정할 특정 Header Cell 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (Header 2줄, 두번째 Column 숨김)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd1" value="header1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd2" value="header2(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd3" value="header3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd4" value="header4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd5" value="header5"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd6" value="header6(H)" hidden="true"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd7" value="header7"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="hd8" value="header8"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" hidden="true" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_setHeaderColor_onclick = function () {
    let cellInfo = par_cellInfo.getText();
    let color = par_color.getText();

    target1.setHeaderColor(cellInfo, color);
    wf_body_bottom.getObj("scwin").setReturnValue("setHeaderColor(" + cellInfo + ", " + color + ")");

    // getHeaderColor 로 설정값 확인
    let rtn = target1.getHeaderColor(cellInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderColor(" + cellInfo + ") : " + rtn);
}
